// FUNCTION: BFME2 0x000CA84D size=111 name=?tossSegments@W3DRopeDraw@@AAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void W3DRopeDraw::tossSegments()
{
	for (std::vector<SegInfo>::iterator it = m_segments.begin(); it != m_segments.end(); ++it)
	{
		if (it->line)
		{
			W3DDisplay::m_3DScene->Remove_Render_Object(it->line);
			if (it->line)
			{
				it->line->Release_Ref();
				it->line = NULL;
			}
		}
		if (it->softLine)
		{
			W3DDisplay::m_3DScene->Remove_Render_Object(it->softLine);
			if (it->softLine)
			{
				it->softLine->Release_Ref();
				it->softLine = NULL;
			}
		}
	}
	m_segments.clear();
}

